        <div style={{ marginBottom: 16 }}>
          <ImportPanel
            onImported={() => {
              setShowImport(false);
              flash('已导入到新题库');
              loadBanks();
            }}
          />
        </div>
      )}

      {banks.length === 0 ? (
        <p className="muted">还没有题库。先新建一个，或去「导入」页灌题。</p>
