          <strong>解析：</strong>
          {question.explanation}
        </div>
      )}

      {!isGraded && (
        <div className="row" style={{ marginTop: 12 }}>
          <button className="btn" disabled={!canSubmit || disabled} onClick={submit}>
            提交作答
          </button>
        </div>
      )}
    </div>
  );
}

